{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Lamivudine, a small polar drug with very high transferability, had absolute oral bioavailability of 68.6 ± 11% in fasted patients, directly supporting high F for the query under fasted conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Saccharin, a small polar imide-like molecule, showed fasted fraction absorbed of 0.88 ± 0.02 versus IV, supporting high oral bioavailability for the similarly polar, low-molecular-weight query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Rolipram, a lactam-containing small molecule, had absolute oral bioavailability of 73 ± 25% in humans, supporting high F for the query's lactam/imide-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Ondansetron, a heterocyclic amide drug, showed approximately 85% absolute oral bioavailability, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Milvexian oral solution under fasted conditions had approximately 100% absolute bioavailability, demonstrating that even larger, more complex lactam-containing molecules can achieve complete oral absorption; this supports high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Fenspiride, a lactam drug, had absolute bioavailability of 90% in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Apixaban, a more complex lactam/amide drug, has approximately 50% absolute oral bioavailability, still well above the 20% threshold, supporting high F for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues, with very high transfer scores, show absolute oral bioavailability well above 20% (roughly 44-100%), and the query is a small polar lactam/imide drug consistent with high oral absorption; therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself; prediction relies on high-transfer analogues.",
    "Some analogue data are from fed or unspecified conditions, but fasted data for lamivudine, saccharin, and milvexian also support high F."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

